"""Webhook request handling for Linkweave billing events."""

from __future__ import annotations

import json
from collections.abc import Mapping
from typing import Any

from event_store import append_event


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and enqueue one payment event."""
    import os

    from signature_utils import verify_signature

    headers = request.get("headers", {})
    body = request.get("body", b"")

    # Signature verification (header-optional for relay compatibility)
    signature = headers.get("X-Webhook-Signature") if isinstance(headers, Mapping) else None
    secret = os.environ.get("WEBHOOK_SECRET", "")
    if signature and not verify_signature(body, signature, secret):
        return {"status": "rejected", "reason": "invalid signature"}

    # Parse JSON body
    try:
        event = json.loads(body.decode("utf-8"))
    except (json.JSONDecodeError, UnicodeDecodeError):
        return {"status": "rejected", "reason": "malformed body"}

    # Validate required event fields
    required_fields = ("event_id", "event_type", "account_id")
    if not all(isinstance(event.get(field), str) for field in required_fields):
        return {"status": "rejected", "reason": "missing required fields"}

    # Append to event store and return accepted response
    append_event(event)
    return {"status": "accepted", "event_id": event["event_id"]}
